import math
from itertools import combinations

def min_angle_pair(vectors):
    def dot_product(v1, v2):
        return v1[0] * v2[0] + v1[1] * v2[1]

    def magnitude(v):
        return math.sqrt(dot_product(v, v))

    def angle_between(v1, v2):
        cos_theta = dot_product(v1, v2) / (magnitude(v1) * magnitude(v2))
        return math.acos(max(-1.0, min(1.0, cos_theta)))

    min_angle = float('inf')
    min_pair = None

    for v1, v2 in combinations(vectors, 2):
        current_angle = angle_between(v1, v2)
        if current_angle < min_angle:
            min_angle = current_angle
            min_pair = (vectors.index(v1) + 1, vectors.index(v2) + 1)

    return min_pair

# Example usage:
n = int(input())
vectors = [tuple(map(int, input().split())) for _ in range(n)]
result = min_angle_pair(vectors)
print(result[0], result[1])

import math
from typing import List, Tuple

def read_vectors() -> List[Tuple[int, int]]:
    n = int(input())
    vectors = []
    for _ in range(n):
        x, y = map(int, input().split())
        vectors.append((x, y))
    return vectors

def calculate_angle(x: int, y: int) -> float:
    if x == 0:
        return math.pi / 2 if y > 0 else 3 * math.pi / 2
    angle = math.atan(abs(y) / abs(x))
    if x < 0:
        angle = math.pi - angle
    elif y < 0:
        angle += 2 * math.pi
    return min(angle, 2 * math.pi - angle)

def find_min_angle_pair(vectors: List[Tuple[int, int]]) -> Tuple[int, int]:
    n = len(vectors)
    angles = [(calculate_angle(x, y), i) for i, (x, y) in enumerate(vectors)]
    angles.sort()

    min_angle = float('inf')
    min_pair = (-1, -1)

    for i in range(n):
        j = (i + 1) % n
        current_angle = abs(angles[i][0] - angles[j][0])
        if current_angle < min_angle:
            min_angle = current_angle
            min_pair = (angles[i][1], angles[j][1])

    return min_pair[0] + 1, min_pair[1] + 1

def main():
    vectors = read_vectors()
    result = find_min_angle_pair(vectors)
    print(result[0], result[1])

if __name__ == "__main__":
    main()

import sys
from math import atan2, pi

def read_vectors():
    n = int(sys.stdin.readline())
    vectors = []
    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        vectors.append((x, y))
    return vectors

def calculate_angle(v1, v2):
    dx, dy = v2[0] - v1[0], v2[1] - v1[1]
    angle = atan2(dy, dx)
    if angle < 0:
        angle += 2 * pi
    return angle

def find_min_non_oriented_angle(vectors):
    min_angle = float('inf')
    min_pair = (-1, -1)

    n = len(vectors)
    for i in range(n):
        for j in range(i + 1, n):
            angle = calculate_angle(vectors[i], vectors[j])
            if angle < min_angle:
                min_angle = angle
                min_pair = (i + 1, j + 1)

    return min_pair

def main():
    vectors = read_vectors()
    result = find_min_non_oriented_angle(vectors)
    print(result[0], result[1])

if __name__ == "__main__":
    main()
